AL_VOID JLPHYGA2XXXPreInitEx(AL_PHY_DevStruct *Phy)
{
    AL_GBE_DevStruct *Gbe = Phy->DevObj;
    AL_U8 PhyAddress = Phy->PhyAddr;

    AL_S32 i, j;
    AL_S32 RegAddr, WriteVal;

    for (i = 0; i < 696; i++) {
        RegAddr = ((InitData[i] >> 16) & 0xff);
        WriteVal = (InitData[i] & 0xffff);
        AlGbe_Dev_WritePhyRegister(Gbe, PhyAddress, RegAddr, WriteVal);
        if (RegAddr == 0x18) {
            AlGbe_Dev_WritePhyRegister(Gbe, PhyAddress, 0x10, 0x8006);
            for (j = 0; j < 8; j++) {
                AL_U16 PhyReg = 1;
                AlGbe_Dev_ReadPhyRegister(Gbe, PhyAddress, 0x10, &PhyReg);
                if (PhyReg == 0) {
                    break;
                }
            }
        }
    }

    AL_U16 RegData;
    AlGbe_Dev_WritePhyRegister(Gbe, PhyAddress, 29, 0x930a);
    AlGbe_Dev_ReadPhyRegister(Gbe, PhyAddress, 29, &RegData);
    printf("page0 reg16=0x%x\r\n", RegData);

    AlGbe_Dev_WritePhyRegister(Gbe, PhyAddress, PHY_PAGE_SELECT_REG, 173);
    RegData = 2;
    AlGbe_Dev_ReadPhyRegister(Gbe, PhyAddress, 16, &RegData);
    printf("page173 reg16=0x%x\r\n", RegData);
    AlGbe_Dev_WritePhyRegister(Gbe, PhyAddress, PHY_PAGE_SELECT_REG, 174);
    AlGbe_Dev_ReadPhyRegister(Gbe, PhyAddress, 16, &RegData);
    printf("page174 reg16=0x%x\r\n", RegData);
}

static AL_S32 AlPhy_JL2101Init(AL_PHY_DevStruct *Phy)
{
    /* Delay at least 10 ms */
    AlSys_MDelay(500);

    JLPHYGA2XXXPreInitEx(Phy);

    return AL_OK;
}

static AL_S32 AlPhy_JL2101GetLinkStatus(AL_PHY_DevStruct *Phy, AL_BOOL *Status)
{
    AL_S32 Ret;
    AL_GBE_DevStruct *Gbe = Phy->DevObj;
    AL_U8 PHYAddress = Phy->PhyAddr;
    AL_U16 RegValue;

    AlGbe_Dev_WritePhyRegister(Gbe, PHYAddress, 0x1f, 0xa43); // change page address;

    do {
        Ret = AlGbe_Dev_ReadPhyRegister(Gbe, PHYAddress, PHY_SSR_REG, &RegValue);
        if (Ret != AL_OK) {
            AL_LOG(AL_LOG_LEVEL_ERROR, "AlGbe_Dev_ReadPhyRegister error:%x\r\n", Ret);
            return Ret;
        }

            //Todo: Timeout
    } while(((PHY_SSTATUS_LINKSTATUS_MASK & RegValue) == 0));

    *Status = AL_TRUE;

    AlGbe_Dev_WritePhyRegister(Gbe, PHYAddress, 0x1f, 0x0); // change page address;

    return AL_OK;
}

static AL_S32 AlPhy_JL2101GetLinkSpeedDuplex(AL_PHY_DevStruct *Phy, AL_U8 *Speed, AL_U8 *Duplex)
{
    AL_S32 Ret;
    AL_GBE_DevStruct *Gbe = Phy->DevObj;
    AL_U8 PHYAddress = Phy->PhyAddr;
    AL_U16 RegValue;

    AlGbe_Dev_WritePhyRegister(Gbe, PHYAddress, 0x1f, 0xa43); // change page address;

    Ret = AlGbe_Dev_ReadPhyRegister(Gbe, PHYAddress, PHY_SSR_REG, &RegValue);
    if (Ret != AL_OK) {
        AL_LOG(AL_LOG_LEVEL_ERROR, "AlGbe_Dev_ReadPhyRegister error:%x\r\n", Ret);
        return Ret;
    }

    switch ((RegValue & PHY_SSTATUS_LINKSPEED_MASK) >> PHY_SSTATUS_LINKSPEED_SHIFT)
    {
    case (AL_U32)PHY_SPEED_10M:
        *Speed = PHY_SPEED_10M;
        printf("LinkSpeed: PHY_SPEED_10M\r\n");
        break;
    case (AL_U32)PHY_SPEED_100M:
        *Speed = PHY_SPEED_100M;
        printf("LinkSpeed: PHY_SPEED_100M\r\n");
        break;
    case (AL_U32)PHY_SPEED_1000M:
        *Speed = PHY_SPEED_1000M;
        printf("LinkSpeed: PHY_SPEED_1000M\r\n");
        break;
    default:
        *Speed = PHY_SPEED_10M;
        break;
    }

    if ((RegValue & PHY_SSTATUS_LINKDUPLEX_MASK) != 0U) {
        *Duplex = PHY_FULL_DUPLEX;
    } else {
        *Duplex = PHY_HALF_DUPLEX;
    }

    AlGbe_Dev_WritePhyRegister(Gbe, PHYAddress, 0x1f, 0x0); // change page address;

    return AL_OK;
}

